<div class="space-y-6"><div><h1 class="text-3xl font-bold">Dashboard</h1><p class="text-slate-400">Estado resumido del sistema.</p></div><section class="grid grid-cols-2 md:grid-cols-4 xl:grid-cols-5 gap-3"><?php $labels=['active_users'=>'Usuarios activos','expired_users'=>'Expirados','connections'=>'Conexiones','active_streams'=>'Streams activos','stream_errors'=>'Streams con errores','movies'=>'Películas','series'=>'Series','episodes'=>'Episodios','resellers'=>'Revendedores','credits_consumed'=>'Créditos consumidos','servers_active'=>'Servidores activos','servers_problem'=>'Servidores con problemas','pending_jobs'=>'Tareas pendientes','storage_bytes'=>'Almacenamiento bytes','security_alerts'=>'Alertas críticas'];foreach($stats as $key=>$value):?><article class="bg-slate-900 border border-slate-800 rounded-xl p-4"><div class="text-xs text-slate-400"><?=htmlspecialchars($labels[$key]??$key)?></div><strong class="text-2xl"><?=number_format($value)?></strong></article><?php endforeach?></section>
<section class="grid md:grid-cols-3 gap-4"><?php foreach(['cpu'=>'CPU total','ram'=>'RAM total'] as $key=>$label):$value=min(100,max(0,(float)($metrics[$key]??0)));?><article class="bg-slate-900 border border-slate-800 rounded-xl p-5"><div class="flex justify-between"><span><?=$label?></span><strong><?=number_format($value,1)?>%</strong></div><div class="h-2 bg-slate-800 rounded mt-3"><div class="h-2 bg-cyan-500 rounded" style="width:<?=$value?>%"></div></div></article><?php endforeach?><article class="bg-slate-900 border border-slate-800 rounded-xl p-5"><span>Tráfico actual</span><strong class="block text-2xl mt-2"><?=number_format((int)($metrics['traffic']??0))?> bps</strong></article></section>
<section class="grid lg:grid-cols-3 gap-4"><div class="bg-slate-900 border border-slate-800 rounded-xl p-4"><h2 class="font-bold mb-3">Alertas</h2><?php foreach($alerts as $a):?><div class="border-b border-slate-800 py-2"><strong class="<?=$a['severity']==='critical'?'text-red-400':'text-amber-400'?>"><?=htmlspecialchars($a['title'])?></strong><div class="text-xs text-slate-400"><?=htmlspecialchars($a['message'])?></div></div><?php endforeach?></div><div class="bg-slate-900 border border-slate-800 rounded-xl p-4"><h2 class="font-bold mb-3">Eventos recientes</h2><?php foreach($events as $e):?><div class="border-b border-slate-800 py-2 text-sm"><?=htmlspecialchars($e['action'])?><div class="text-xs text-slate-500"><?=$e['created_at']?></div></div><?php endforeach?></div><div class="bg-slate-900 border border-slate-800 rounded-xl p-4"><h2 class="font-bold mb-3">Tareas</h2><?php foreach($jobs as $j):?><div class="border-b border-slate-800 py-2"><div class="flex justify-between"><span><?=htmlspecialchars($j['type'])?></span><span><?=$j['progress']?>%</span></div><div class="h-1 bg-slate-800"><div class="h-1 bg-cyan-500" style="width:<?=$j['progress']?>%"></div></div></div><?php endforeach?></div></section></div>
